import React, { useState, useEffect } from 'react';
import axios from 'axios';
import toast, { Toaster } from 'react-hot-toast';
import { 
  FaUser, FaEnvelope, FaPhone, FaCalendar, FaGraduationCap, 
  FaChurch, FaMapMarkerAlt, FaDollarSign, FaUsers, FaShieldAlt,
  FaEye, FaEyeSlash, FaTrash, FaHeart, FaLightbulb, FaHandsHelping,
  FaCross, FaUniversity, FaMobileAlt, FaMapMarker
} from 'react-icons/fa';

function App() {
  const [formData, setFormData] = useState({
    surname: '', given_name: '', institution: '', dob: '', sex: '', marital_status: '',
    home_province: '', country: 'Papua New Guinea', denomination: '', address: '', 
    phone: '', mobile: '', email: '',
    college_university: '', member_role: '', leader_position: '', year_of_graduation: '', field_of_study: '',
    graduate_program: '', fortnightly_amount: '', monthly_amount: '', yearly_amount: '',
    donation_amount: '', membership_type: '', membership_amount: '', 
    membership_new_renewal: 'New', membership_number: ''
  });

  const [members, setMembers] = useState([]);
  const [showAdmin, setShowAdmin] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // TSCF Theme Colors
  const colors = {
    primary: '#0b2b5c',      // Deep navy blue from logo
    primaryLight: '#1a3f7a',
    accent: '#c49a2c',        // Gold/amber accent
    accentLight: '#e8c468',
    secondary: '#8b2c1d',     // Burgundy/crimson
    softBg: '#f5f3f0'
  };

  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      const response = await axios.get('/api/members');
      setMembers(response.data);
    } catch (err) {
      toast.error('Failed to fetch members');
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await axios.post('/api/members', formData);
      toast.success('Application submitted successfully!');
      setFormData({
        surname: '', given_name: '', institution: '', dob: '', sex: '', marital_status: '',
        home_province: '', country: 'Papua New Guinea', denomination: '', address: '', 
        phone: '', mobile: '', email: '',
        college_university: '', member_role: '', leader_position: '', year_of_graduation: '', field_of_study: '',
        graduate_program: '', fortnightly_amount: '', monthly_amount: '', yearly_amount: '',
        donation_amount: '', membership_type: '', membership_amount: '', 
        membership_new_renewal: 'New', membership_number: ''
      });
      fetchMembers();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      toast.error('Error submitting application. Email may already exist.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateStatus = async (id, status) => {
    try {
      await axios.put(`/api/members/${id}/status`, { application_status: status });
      toast.success(`Application ${status}`);
      fetchMembers();
    } catch (err) {
      toast.error('Failed to update status');
    }
  };

  const deleteMember = async (id) => {
    if (window.confirm('Are you sure you want to delete this application?')) {
      try {
        await axios.delete(`/api/members/${id}`);
        toast.success('Application deleted');
        fetchMembers();
      } catch (err) {
        toast.error('Failed to delete');
      }
    }
  };

  const graduatePrograms = [
    'Moore Bible College', 'Queensland Theological Seminary', 'Ministry Apprentice (MA)',
    'SAIACS - India', 'Corporate Training', 'Ministry Training Program', 
    'Seminars', 'Conferences', 'Empowerment Training'
  ];

  const membershipTypes = [
    { type: 'Student Member', amount: 20, icon: FaGraduationCap, description: 'K20 / year' },
    { type: 'Graduate Member', amount: 200, icon: FaUser, description: 'K200 / year' },
    { type: 'Life Member', amount: 2500, icon: FaHeart, description: 'K2500 (one-off)' },
    { type: 'Partner', amount: 0, icon: FaHandsHelping, description: 'Open amount' }
  ];

  const getStatusColor = (status) => {
    switch(status) {
      case 'approved': return 'bg-green-100 text-green-700';
      case 'rejected': return 'bg-red-100 text-red-700';
      default: return 'bg-yellow-100 text-yellow-700';
    }
  };

  return (
    <div className="min-h-screen" style={{ background: 'linear-gradient(145deg, #eef2f7 0%, #e4e9f0 100%)' }}>
      <Toaster position="top-right" />

      {/* Header Section with TSCF Logo Colors */}
      <header style={{ background: `linear-gradient(135deg, ${colors.primary} 0%, #123b6e 50%, #1f4a7a 100%)` }} className="text-white shadow-2xl">
        <div className="container mx-auto px-4 py-8 md:py-10">
          <div className="flex flex-col md:flex-row items-center justify-between gap-6">
            <div className="flex items-center gap-4 flex-wrap justify-center">
              {/* Logo Badge */}
              <div className="bg-white rounded-full w-20 h-20 flex items-center justify-center shadow-lg">
                <div className="text-center">
                  <span className="font-black text-2xl" style={{ color: colors.primary }}>TSCF</span>
                  <span className="block text-[10px] font-bold" style={{ color: colors.secondary }}>CHRISTIAN<br/>FELLOWSHIP</span>
                </div>
              </div>
              <div className="text-center md:text-left">
                <h1 className="text-xl md:text-3xl font-extrabold tracking-tight">TERTIARY STUDENTS CHRISTIAN FELLOWSHIP</h1>
                <div className="text-sm text-indigo-100 mt-1 space-y-0.5">
                  <p><FaMapMarker className="inline mr-1 text-amber-300" /> NATIONAL MEMBERSHIP · P. O. Box 6329 Port Boroko, National Capital District</p>
                  <p><FaMobileAlt className="inline mr-1 text-amber-300" /> Mobile: 73277901</p>
                </div>
              </div>
            </div>
            <div className="bg-white/15 backdrop-blur-sm rounded-2xl px-6 py-3 text-center border border-white/20">
              <div className="text-xs uppercase tracking-wider">The Voice of Truth</div>
              <div className="text-2xl font-black italic">SALT & LIGHT</div>
            </div>
          </div>

          {/* Vision, Mission, Core Values Section */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5 mt-8 pt-4 border-t border-white/20">
            <div className="bg-white/5 p-4 rounded-xl text-center backdrop-blur-sm">
              <FaLightbulb className="text-2xl text-amber-300 mx-auto mb-2" />
              <h3 className="font-bold text-amber-200">Our Vision</h3>
              <p className="text-xs text-gray-100 leading-relaxed">To mobilize and facilitate the movement of graduates to impact the marketplace and the nation towards national salvation and transformation</p>
            </div>
            <div className="bg-white/5 p-4 rounded-xl text-center backdrop-blur-sm">
              <FaUsers className="text-2xl text-amber-300 mx-auto mb-2" />
              <h3 className="font-bold text-amber-200">Our Mission</h3>
              <p className="text-xs text-gray-100 leading-relaxed">By promoting a kingdom mindset through divine alignment, strategic alliance, partnership and fellowship amongst all graduates to become gatekeepers in our nation.</p>
            </div>
            <div className="bg-white/5 p-4 rounded-xl text-center backdrop-blur-sm">
              <FaShieldAlt className="text-2xl text-amber-300 mx-auto mb-2" />
              <h3 className="font-bold text-amber-200">Core Values</h3>
              <p className="text-xs text-gray-100 leading-relaxed">Truth (God's Word), Servant Leadership, Integrity, Teamwork, Empowerment, Partnership and Advocacy</p>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="container mx-auto px-4 py-8">
        {/* Title */}
        <div className="text-center mb-8">
          <h2 className="text-3xl md:text-4xl font-black tracking-tight" style={{ color: colors.primary }}>TSCF VISION PARTNERS FORM 2026</h2>
          <div className="w-28 h-1 mx-auto mt-2 rounded-full" style={{ background: colors.accent }}></div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Section 1: GENERAL INFORMATION */}
          <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
            <div className="px-6 py-4 border-b border-gray-200 flex items-center gap-3" style={{ background: colors.softBg }}>
              <span className="w-8 h-8 rounded-full flex items-center justify-center text-white text-sm font-bold" style={{ background: colors.primary }}>1</span>
              <h3 className="text-xl font-bold" style={{ color: colors.primary }}>GENERAL INFORMATION</h3>
            </div>
            <div className="p-6 space-y-5">
              <div className="grid md:grid-cols-2 gap-5">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Surname</label>
                  <input name="surname" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 transition-all" style={{ focusRingColor: colors.accent, borderColor: '#d1d5db' }} value={formData.surname} onChange={handleChange} required />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Given Name</label>
                  <input name="given_name" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl focus:outline-none focus:ring-2" style={{ focusRingColor: colors.accent }} value={formData.given_name} onChange={handleChange} required />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Institution</label>
                  <input name="institution" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.institution} onChange={handleChange} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Date of Birth</label>
                  <input type="date" name="dob" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.dob} onChange={handleChange} />
                </div>
              </div>

              {/* Sex: Tick Male/Female */}
              <div className="flex flex-wrap items-center gap-6">
                <span className="font-semibold text-gray-700 w-24">Sex: (Tick)</span>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input type="radio" name="sex" value="Male" checked={formData.sex === 'Male'} onChange={handleChange} className="w-4 h-4" style={{ accentColor: colors.accent }} /> 
                  <span>Male</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input type="radio" name="sex" value="Female" checked={formData.sex === 'Female'} onChange={handleChange} className="w-4 h-4" style={{ accentColor: colors.accent }} /> 
                  <span>Female</span>
                </label>
              </div>

              {/* Marital Status: Tick options */}
              <div className="flex flex-wrap items-center gap-6">
                <span className="font-semibold text-gray-700 w-24">Marital Status:</span>
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="marital_status" value="Married" checked={formData.marital_status === 'Married'} onChange={handleChange} /> Married</label>
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="marital_status" value="Single" checked={formData.marital_status === 'Single'} onChange={handleChange} /> Single</label>
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="marital_status" value="Divorced" checked={formData.marital_status === 'Divorced'} onChange={handleChange} /> Divorced</label>
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="marital_status" value="Other" checked={formData.marital_status === 'Other'} onChange={handleChange} /> Other</label>
              </div>

              <div className="grid md:grid-cols-2 gap-5">
                <div><label className="block text-sm font-semibold text-gray-700 mb-1">Home Province</label><input name="home_province" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.home_province} onChange={handleChange} /></div>
                <div><label className="block text-sm font-semibold text-gray-700 mb-1">Country</label><input name="country" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.country} onChange={handleChange} /></div>
                <div><label className="block text-sm font-semibold text-gray-700 mb-1">Denomination</label><input name="denomination" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.denomination} onChange={handleChange} /></div>
                <div className="md:col-span-2"><label className="block text-sm font-semibold text-gray-700 mb-1">Address</label><textarea name="address" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" rows="2" value={formData.address} onChange={handleChange}></textarea></div>
                <div><label className="block text-sm font-semibold text-gray-700 mb-1"><FaPhone className="inline mr-1" /> Phone</label><input name="phone" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.phone} onChange={handleChange} /></div>
                <div><label className="block text-sm font-semibold text-gray-700 mb-1"><FaMobileAlt className="inline mr-1" /> Mobile</label><input name="mobile" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.mobile} onChange={handleChange} /></div>
                <div className="md:col-span-2"><label className="block text-sm font-semibold text-gray-700 mb-1"><FaEnvelope className="inline mr-1" /> Email</label><input type="email" name="email" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.email} onChange={handleChange} required /></div>
              </div>
            </div>
          </div>

          {/* Section 2: EDUCATIONAL INFORMATION */}
          <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
            <div className="px-6 py-4 border-b border-gray-200 flex items-center gap-3" style={{ background: colors.softBg }}>
              <span className="w-8 h-8 rounded-full flex items-center justify-center text-white text-sm font-bold" style={{ background: colors.primary }}>2</span>
              <h3 className="text-xl font-bold" style={{ color: colors.primary }}>EDUCATIONAL INFORMATION</h3>
            </div>
            <div className="p-6 space-y-5">
              <div><label className="block text-sm font-semibold text-gray-700 mb-1">College/University attended</label><input name="college_university" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.college_university} onChange={handleChange} /></div>
              <div className="grid md:grid-cols-3 gap-5">
                <div><label className="block text-sm font-semibold text-gray-700 mb-1">As a member:</label><input name="member_role" placeholder="Member / Leader" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.member_role} onChange={handleChange} /></div>
                <div><label className="block text-sm font-semibold text-gray-700 mb-1">As Leader:</label><input name="leader_position" placeholder="Position held" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.leader_position} onChange={handleChange} /></div>
                <div><label className="block text-sm font-semibold text-gray-700 mb-1">Year of Graduation</label><input type="number" name="year_of_graduation" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.year_of_graduation} onChange={handleChange} /></div>
              </div>
              <div><label className="block text-sm font-semibold text-gray-700 mb-1">Field of Study</label><input name="field_of_study" className="w-full px-4 py-2.5 border border-gray-300 rounded-xl" value={formData.field_of_study} onChange={handleChange} /></div>
            </div>
          </div>

          {/* Section 3: PARTNERS PROGRAMS */}
          <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
            <div className="px-6 py-4 border-b border-gray-200 flex items-center gap-3" style={{ background: colors.softBg }}>
              <span className="w-8 h-8 rounded-full flex items-center justify-center text-white text-sm font-bold" style={{ background: colors.primary }}>3</span>
              <h3 className="text-xl font-bold" style={{ color: colors.primary }}>PARTNERS PROGRAMS</h3>
            </div>
            <div className="p-6 space-y-6">
              <div className="bg-amber-50/40 p-5 rounded-xl border" style={{ borderColor: colors.accentLight }}>
                <label className="block text-sm font-semibold text-gray-800 mb-3">Graduate Programs (Select one)</label>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                  {graduatePrograms.map(program => (
                    <label key={program} className="flex items-center gap-2 cursor-pointer">
                      <input type="radio" name="graduate_program" value={program} checked={formData.graduate_program === program} onChange={handleChange} style={{ accentColor: colors.accent }} />
                      <span className="text-sm">{program}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Donation Amounts */}
              <div className="bg-gray-50 rounded-xl p-5">
                <label className="block text-sm font-semibold text-gray-800 mb-3 flex items-center gap-2"><FaDollarSign style={{ color: colors.accent }} /> Donation Amounts (Kina)</label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div><label className="text-xs text-gray-500">Fortnightly (K)</label><input type="number" step="0.01" name="fortnightly_amount" className="w-full px-3 py-2 border border-gray-300 rounded-lg" value={formData.fortnightly_amount} onChange={handleChange} /></div>
                  <div><label className="text-xs text-gray-500">Monthly (K)</label><input type="number" step="0.01" name="monthly_amount" className="w-full px-3 py-2 border border-gray-300 rounded-lg" value={formData.monthly_amount} onChange={handleChange} /></div>
                  <div><label className="text-xs text-gray-500">Yearly (K)</label><input type="number" step="0.01" name="yearly_amount" className="w-full px-3 py-2 border border-gray-300 rounded-lg" value={formData.yearly_amount} onChange={handleChange} /></div>
                  <div><label className="text-xs text-gray-500">One-time Donation</label><input type="number" step="0.01" name="donation_amount" className="w-full px-3 py-2 border border-gray-300 rounded-lg" value={formData.donation_amount} onChange={handleChange} /></div>
                </div>
              </div>

              {/* Banking Details */}
              <div className="rounded-xl p-4 border-l-8" style={{ background: '#eef2fa', borderLeftColor: colors.accent }}>
                <p className="font-bold" style={{ color: colors.primary }}><FaUniversity className="inline mr-2" /> TSCF Banking details</p>
                <p className="font-mono text-sm">Tertiary Students Christian Fellowship<br />Account: 1000435676 | Bank South Pacific, Boroko Banking Centre<br />BSB NO: 088-943 | SWIFT CODE: BOSPPGPM</p>
              </div>
            </div>
          </div>

          {/* Section 4: TYPE OF MEMBERSHIP */}
          <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
            <div className="px-6 py-4 border-b border-gray-200 flex items-center gap-3" style={{ background: colors.softBg }}>
              <span className="w-8 h-8 rounded-full flex items-center justify-center text-white text-sm font-bold" style={{ background: colors.primary }}>4</span>
              <h3 className="text-xl font-bold" style={{ color: colors.primary }}>TYPE OF MEMBERSHIP</h3>
            </div>
            <div className="p-6 space-y-5">
              <div className="flex flex-wrap gap-6">
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="membership_new_renewal" value="New" checked={formData.membership_new_renewal === 'New'} onChange={handleChange} /> <span className="font-semibold">New Application</span></label>
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="membership_new_renewal" value="Renewal" checked={formData.membership_new_renewal === 'Renewal'} onChange={handleChange} /> <span className="font-semibold">Renewal</span></label>
                {formData.membership_new_renewal === 'Renewal' && (
                  <div><label className="text-sm text-gray-600">Membership No.</label><input name="membership_number" className="ml-2 px-3 py-1.5 border border-gray-300 rounded-lg w-40" value={formData.membership_number} onChange={handleChange} /></div>
                )}
              </div>
              <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                {membershipTypes.map((mt, idx) => (
                  <label key={idx} className="border-2 rounded-xl p-3 cursor-pointer hover:shadow-md transition-all" style={{ borderColor: formData.membership_type === mt.type ? colors.accent : '#e5e7eb' }}>
                    <input type="radio" name="membership_type" value={mt.type} checked={formData.membership_type === mt.type} onChange={handleChange} className="mr-2" style={{ accentColor: colors.accent }} />
                    <mt.icon className="inline mr-2" style={{ color: colors.primary }} />
                    <span className="font-semibold">{mt.type}</span>
                    <p className="text-xs text-gray-500 mt-1">{mt.description}</p>
                  </label>
                ))}
              </div>
              <div><label className="block text-sm font-semibold text-gray-700 mb-1">Custom Amount (Kina)</label><input type="number" step="0.01" name="membership_amount" className="w-48 px-4 py-2 border border-gray-300 rounded-lg" placeholder="Enter amount" value={formData.membership_amount} onChange={handleChange} /></div>
            </div>
          </div>

          {/* Submit Button */}
          <div className="text-center">
            <button type="submit" disabled={isSubmitting} className="text-white font-bold py-3 px-12 rounded-full text-lg shadow-lg transition-all hover:scale-105 disabled:opacity-50" style={{ background: `linear-gradient(95deg, ${colors.primary}, ${colors.primaryLight})` }}>
              {isSubmitting ? 'Submitting...' : 'Submit Application'}
            </button>
          </div>
        </form>

        {/* Admin Panel Toggle */}
        <div className="mt-12 text-center">
          <button onClick={() => setShowAdmin(!showAdmin)} className="px-6 py-2 rounded-full text-white shadow-md transition-all" style={{ background: colors.primary }}>
            {showAdmin ? <><FaEyeSlash className="inline mr-2" />Hide Admin Panel</> : <><FaEye className="inline mr-2" />Show Admin Panel</>}
          </button>
        </div>

        {/* Admin Dashboard */}
        {showAdmin && (
          <div className="mt-6 bg-white rounded-2xl shadow-xl p-6 overflow-x-auto">
            <h3 className="text-2xl font-bold mb-6" style={{ color: colors.primary }}>Admin Dashboard</h3>
            <table className="w-full text-sm">
              <thead className="text-white" style={{ background: colors.primary }}>
                <tr><th className="p-3 text-left">ID</th><th className="p-3 text-left">Surname</th><th className="p-3 text-left">Given Name</th><th className="p-3 text-left">Email</th><th className="p-3 text-left">Membership</th><th className="p-3 text-left">Status</th><th className="p-3 text-left">Actions</th></tr>
              </thead>
              <tbody>
                {members.map(member => (
                  <tr key={member.id} className="border-b hover:bg-gray-50">
                    <td className="p-3">{member.id}</td>
                    <td className="p-3">{member.surname}</td>
                    <td className="p-3">{member.given_name}</td>
                    <td className="p-3">{member.email}</td>
                    <td className="p-3">{member.membership_type || 'N/A'}</td>
                    <td className="p-3"><span className={`px-2 py-1 rounded-full text-xs font-semibold ${getStatusColor(member.application_status)}`}>{member.application_status}</span></td>
                    <td className="p-3 space-x-2">
                      <select onChange={(e) => updateStatus(member.id, e.target.value)} value={member.application_status} className="px-2 py-1 border rounded text-sm">
                        <option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option>
                      </select>
                      <button onClick={() => deleteMember(member.id)} className="text-red-600 hover:text-red-800"><FaTrash /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Footer */}
      <footer style={{ background: '#0a2540' }} className="text-white/80 mt-16">
        <div className="container mx-auto px-4 py-8 text-center">
          <div className="flex justify-center gap-2 items-center mb-3">
            <FaCross className="text-amber-400" />
            <span className="font-semibold tracking-wide">Tertiary Students Christian Fellowship</span>
          </div>
          <p className="text-sm">TSCF Vision Partners Application Form 2026</p>
          <p className="text-xs mt-2 opacity-70">&copy; Tertiary Students Christian Fellowship 2026. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
